BEGIN
 SELECT id INTO STRICT cid FROM public.campuses WHERE slug='futa-main';
 INSERT INTO public.departments(name,faculty,slug,sort_order,campus_id,is_active)
 SELECT name,faculty,slug,sort_order,cid,true FROM jsonb_to_recordset(items) AS i(name text,faculty text,slug text,sort_order integer)
 ON CONFLICT(campus_id,lower(name)) DO UPDATE SET faculty=excluded.faculty,slug=excluded.slug,sort_order=excluded.sort_order,is_active=true,updated_at=now();
 -- Existing profile department IDs stay valid; refresh FUTA's denormalized faculty.
 UPDATE public.profiles p SET faculty=i.faculty
 FROM jsonb_to_recordset(items) AS i(name text,faculty text) WHERE p.campus_id=cid AND lower(p.department)=lower(i.name);
 IF (SELECT count(*) FROM public.departments d JOIN jsonb_to_recordset(items) AS i(name text,faculty text) ON d.name=i.name AND d.faculty=i.faculty WHERE d.campus_id=cid AND d.is_active)<>51 THEN RAISE EXCEPTION 'FUTA department verification failed'; END IF;
END $data$;
COMMIT;
SELECT count(*) AS departments,count(DISTINCT d.faculty) AS schools FROM public.departments d JOIN public.campuses c ON c.id=d.campus_id WHERE c.slug='futa-main' AND d.is_active;
